def transform(grid):
    from collections import Counter
    from functools import lru_cache

    h, w = len(grid), len(grid[0])

    def components(r0, r1, c0, c1, background):
        cells = {
            (r, c): grid[r][c]
            for r in range(r0, r1)
            for c in range(c0, c1)
            if grid[r][c] != background
        }
        unseen = set(cells)
        pieces = []
        while unseen:
            start = min(unseen)
            unseen.remove(start)
            stack = [start]
            piece = []
            while stack:
                r, c = stack.pop()
                piece.append((r, c, cells[(r, c)]))
                for nr, nc in ((r - 1, c), (r + 1, c),
                               (r, c - 1), (r, c + 1)):
                    if (nr, nc) in unseen:
                        unseen.remove((nr, nc))
                        stack.append((nr, nc))
            pieces.append(piece)
        return pieces

    def pack(mask_coords, pieces, th, tw):
        n = len(mask_coords)
        if not n or not pieces:
            return None

        index = {p: i for i, p in enumerate(mask_coords)}
        shape_counts = Counter()
        for piece in pieces:
            mr = min(r for r, c, v in piece)
            mc = min(c for r, c, v in piece)
            shape = tuple(sorted((r - mr, c - mc, v) for r, c, v in piece))
            shape_counts[shape] += 1

        shapes = list(shape_counts)
        remaining = tuple(shape_counts[s] for s in shapes)
        areas = [len(s) for s in shapes]
        if sum(remaining[i] * areas[i] for i in range(len(shapes))) != n:
            return None

        by_cell = [[] for _ in range(n)]
        for ti, shape in enumerate(shapes):
            ph = max(r for r, c, v in shape) + 1
            pw = max(c for r, c, v in shape) + 1
            if ph > th or pw > tw:
                continue
            for top in range(th - ph + 1):
                for left in range(tw - pw + 1):
                    vals = []
                    cover = 0
                    for dr, dc, color in shape:
                        q = index.get((top + dr, left + dc))
                        if q is None:
                            break
                        vals.append((q, color))
                        cover |= 1 << q
                    else:
                        placement = (ti, cover, tuple(vals))
                        for q, color in vals:
                            by_cell[q].append(placement)

        full = (1 << n) - 1

        @lru_cache(maxsize=None)
        def solve(uncovered, rem):
            if uncovered == 0:
                return () if not any(rem) else None

            if sum(rem[i] * areas[i] for i in range(len(shapes))) != uncovered.bit_count():
                return None

            best_options = None
            bits = uncovered
            while bits:
                low = bits & -bits
                q = low.bit_length() - 1
                options = []
                for placement in by_cell[q]:
                    ti, cover, vals = placement
                    if rem[ti] and (cover & uncovered) == cover:
                        options.append(placement)
                if not options:
                    return None
                if best_options is None or len(options) < len(best_options):
                    best_options = options
                bits ^= low

            best_options.sort(key=lambda p: -p[1].bit_count())
            for ti, cover, vals in best_options:
                new_rem = list(rem)
                new_rem[ti] -= 1
                tail = solve(uncovered ^ cover, tuple(new_rem))
                if tail is not None:
                    return (vals,) + tail
            return None

        solution = solve(full, remaining)
        if solution is None:
            return None

        colors = [None] * n
        for vals in solution:
            for q, color in vals:
                colors[q] = color
        return colors if all(color is not None for color in colors) else None

    def attempt(axis, pos, line_color, source_before):
